// src/pages/services.tsx
import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import Link from "../components/AppLink";
import EntityTrustPanel from "../components/EntityTrustPanel";
import Layout from "../components/Layout";
import VerticalLinksGrid from "../components/VerticalLinksGrid";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import images from "../images";
import { useEffect } from "react";
import SEO from "../components/seo";
import I18nHeadProvider from "../components/I18nHeadProvider";
import {
  buildBreadcrumbListSchema,
  buildServiceItemListSchema,
  localizeSitePath,
} from "../utils/structuredData";
import { VERTICAL_ORDER, getVerticalConfig } from "../utils/verticals";

const info: Company = data[0];

type Chip = { chip: string };
type ServiceCard = {
  slug: string;
  title: string;
  subtitle: string;
  bullets: Array<{ item: string }>;
};
type ProfilePoint = { item: string };

const ServicesHubPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const heroChips = t("servicesHub.hero.chips", {
    returnObjects: true,
  }) as Chip[];
  const profilePoints = t("about.profile.points", {
    returnObjects: true,
  }) as ProfilePoint[];
  const cards = t("servicesHub.services", {
    returnObjects: true,
  }) as ServiceCard[];
  const verticalItems = VERTICAL_ORDER.map((verticalKey) => {
    const config = getVerticalConfig(verticalKey);

    return {
      to: config.path,
      title: t(`verticalsHub.items.${verticalKey}.title`) as string,
      text: t(`verticalsHub.items.${verticalKey}.text`) as string,
    };
  });

  const whatsappHref = info.whatsapp;

  return (
    <Layout data={info}>
      {/* HERO */}
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-5xl">
              {t("servicesHub.hero.title")}
            </h1>

            <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
              {t("servicesHub.hero.subtitle")}
            </p>

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t("servicesHub.hero.primaryCta")}
              </Link>

              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
              >
                {t("servicesHub.hero.secondaryCta")}
              </a>
            </div>

            {/* Proof chips */}
            {Array.isArray(heroChips) && heroChips.length > 0 ? (
              <div className="mx-auto mt-6 flex flex-wrap items-center justify-center gap-2 max-w-4xl">
                {heroChips.map((c, idx) => (
                  <span
                    key={`${c.chip}-${idx}`}
                    className="inline-flex items-center rounded-full border border-white/20 bg-white/10 px-3 py-1 text-sm text-light/90"
                  >
                    {c.chip}
                  </span>
                ))}
              </div>
            ) : null}
          </div>
        </div>
      </section>

      <div className={styles.container}>
        <EntityTrustPanel
          eyebrow={t("about.profile.eyebrow") as string}
          name={info.founder?.name || info.companyName}
          role={t("about.profile.role") as string}
          summary={t("about.profile.summary") as string}
          highlights={Array.isArray(profilePoints) ? profilePoints.map((point) => point.item) : []}
          primaryHref="/about/"
          primaryLabel={t("menu.about") as string}
          secondaryHref="/portfolio/"
          secondaryLabel={t("menu.portfolio") as string}
        />
      </div>

      {/* SERVICES GRID */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("servicesHub.gridTitle")}
          </h2>

          <p className="mt-4 text-sm sm:text-base text-center text-light/70 max-w-4xl mx-auto">
            {t("servicesHub.gridSubtitle")}
          </p>

          <div className="mt-10 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(cards)
              ? cards.map((svc, idx) => (
                  <div key={`${svc.slug}-${idx}`} className={styles.card}>
                    <div className="flex items-start justify-between gap-4">
                      <div>
                        <h3 className="text-lg sm:text-xl font-semibold text-light/90">
                          {svc.title}
                        </h3>
                        <p className="mt-2 text-sm sm:text-base text-light/70 leading-relaxed">
                          {svc.subtitle}
                        </p>
                      </div>
                    </div>

                    {Array.isArray(svc.bullets) && svc.bullets.length > 0 ? (
                      <ul className="mt-4 list-disc pl-5 space-y-2 text-sm text-light/80">
                        {svc.bullets.map((b, bIdx) => (
                          <li key={`${b.item}-${bIdx}`}>{b.item}</li>
                        ))}
                      </ul>
                    ) : null}

                    <div className="mt-6 flex items-center justify-between gap-3">
                      <Link
                        to={svc.slug}
                        className="inline-flex rounded-full bg-secondary px-4 py-2 text-light text-center"
                      >
                        {t("servicesHub.learnMore")}
                      </Link>
                      <Link
                        to="/contact/"
                        className="text-sm underline text-light/70"
                      >
                        {t("servicesHub.contactLink")}
                      </Link>
                    </div>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* HOW TO CHOOSE */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("servicesHub.howToChoose.title")}
            </h2>

            <div className="mt-8 space-y-3">
              {(
                t("servicesHub.howToChoose.items", {
                  returnObjects: true,
                }) as Array<{
                  title: string;
                  text: string;
                }>
              ).map((x, idx) => (
                <div key={`${x.title}-${idx}`} className={styles.card}>
                  <h3 className="text-base sm:text-lg font-semibold text-light/90">
                    {x.title}
                  </h3>
                  <p className="mt-2 text-sm sm:text-base text-light/70 leading-relaxed">
                    {x.text}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      <VerticalLinksGrid
        eyebrow={t("verticalsHub.eyebrow") as string}
        title={t("verticalsHub.title") as string}
        subtitle={t("verticalsHub.subtitle") as string}
        items={verticalItems}
        ctaLabel={t("verticalsHub.ctaLabel") as string}
      />

      {/* FINAL CTA */}
      <section className="py-12 sm:py-16">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl text-center">
            <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
              {t("servicesHub.finalCta.title")}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/70">
              {t("servicesHub.finalCta.subtitle")}
            </p>

            <div className="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t("servicesHub.finalCta.primaryCta")}
              </Link>

              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
              >
                {t("servicesHub.finalCta.secondaryCta")}
              </a>
            </div>
          </div>
        </div>
      </section>
    </Layout>
  );
};

const ServicesHubHeadContent: React.FC = () => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();
  const cards = t("servicesHub.services", {
    returnObjects: true,
  }) as ServiceCard[];

  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.servicesHub.nav") as string,
      path: localizeSitePath("/services/", language, defaultLanguage),
    },
  ]);
  const serviceItemListSchema = buildServiceItemListSchema(
    info.url,
    localizeSitePath("/services/", language, defaultLanguage),
    Array.isArray(cards)
      ? cards.map((service) => ({
          name: service.title,
          description: service.subtitle,
          path: localizeSitePath(service.slug, language, defaultLanguage),
        }))
      : [],
    t("servicesHub.gridTitle") as string
  );
  const additionalSchemas = [breadcrumbSchema, serviceItemListSchema].filter(
    Boolean
  ) as object[];

  return (
    <SEO
      data={info}
      titleKey="servicesHub.metaTitle"
      descriptionKey="servicesHub.metaDescription"
      pathname="/services/"
      schemaType="ProfessionalService"
      pageSchemaType="CollectionPage"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <ServicesHubHeadContent />
  </I18nHeadProvider>
);

export default ServicesHubPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  sectionWrapper:
    "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
  labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
  container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
  card: "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
  cardTitle: "text-base sm:text-lg font-semibold text-light/90",
  cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
